    def norm_status(s):
        return re.sub(r"[^a-z]", "", str(s or "").lower())

    loc_tz = {}
    for loc in data.get("locations", []):
        name = str(loc.get("location", "")).strip()
        tz = loc.get("timezone")
        if name and tz:
            loc_tz[name] = tz

    provider_names = {}
    for p in data.get("providers", []):
        pname = str(p.get("provider", "")).strip()
        if pname:
            provider_names[pname.lower()] = pname

