        if norm_status(appt.get("status")) != "noshow":
            continue

        loc_name = str(appt.get("location", "")).strip()
        tz_name = loc_tz.get(loc_name, "America/Denver")

        ts = str(appt.get("start_utc", "")).strip()
        try:
            dt_utc = datetime.strptime(ts, "%Y-%m-%dT%H:%M:%SZ")
        except ValueError:
            try:
                dt_utc = datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
            except ValueError:
                continue
        dt_utc = dt_utc.replace(tzinfo=ZoneInfo("UTC"))
        local = dt_utc.astimezone(ZoneInfo(tz_name))

        if local.year != 2025:
            continue

        provider = str(appt.get("provider", "")).strip()
        if not provider:
            continue
        provider = provider_names.get(provider.lower(), provider)
