    if not counts:
        return ""

    best = max(counts.items(), key=lambda kv: (kv[1], -ord(kv[0][0]) if kv[0] else 0))
    top_count = best[1]
    tied = sorted(name for name, c in counts.items() if c == top_count)
    return tied[0]
